"""Versioned Russian curriculum. Every lesson has an executable exercise."""


def lesson(id, module, title, minutes, goal, theory, example, breakdown, tip, task, starter, hints, checks):
    return dict(id=id, module=module, title=title, minutes=minutes, goal=goal,
                theory=theory, example=example, breakdown=breakdown, tip=tip,
                task=task, starter=starter, hints=hints, checks=checks)


